import java.util.*;
import java.io.*;

public class Main {
    static int[] impactedTasks(int n, int[][] deps, int s) {
        // Write your solution here
        // deps[i] = {a, b} means task b depends on task a.
        // Return new int[]{-1} if no task is impacted.
        return new int[0];
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int n = (int) in.nval;
        in.nextToken();
        int m = (int) in.nval;
        in.nextToken();
        int s = (int) in.nval;
        int[][] deps = new int[m][2];
        for (int i = 0; i < m; i++) {
            in.nextToken(); deps[i][0] = (int) in.nval;
            in.nextToken(); deps[i][1] = (int) in.nval;
        }
        int[] res = impactedTasks(n, deps, s);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < res.length; i++) sb.append(res[i]).append(i + 1 < res.length ? " " : "\n");
        System.out.print(sb);
    }
}
